// ==========================================================
// Detectar modelo: convierte el modelo que escribió el cliente en el groupR de Ford
// ==========================================================
// Si Ford ya conoce el vehículo (Ford - Buscar Vehiculo trae modelGroup), se usa ese.
// Si no, se busca el texto del cliente (campo "modelo" del trigger) en esta tabla.

// La Ranger nueva (P703) es otro groupR: si el cliente dice el año, se usa para decidir
const RANGER_NUEVA_DESDE = 2023;

// groupR -> nombres con los que lo puede escribir el cliente.
// Ids y nombres del catálogo de Agenda Ford: GET /agenda-scheduling/api/internal/modelVehicle/ARG/1
// (el 3 es un FIESTA duplicado en AF: se usa el 2)
const MODELOS = [
  { groupR: 1,  nombre: 'KA',                   alias: ['ka', 'ka plus', 'ka+', 'ka freestyle'] },
  { groupR: 2,  nombre: 'FIESTA',               alias: ['fiesta', 'fiesta kinetic', 'fiesta max'] },
  { groupR: 4,  nombre: 'ECOSPORT',             alias: ['ecosport', 'eco sport'] },
  { groupR: 6,  nombre: 'FOCUS',                alias: ['focus'] },
  { groupR: 8,  nombre: 'S-MAX',                alias: ['s max', 'smax'] },
  { groupR: 9,  nombre: 'RANGER',               alias: [] },                 // Ranger anterior: se elige por año, ver RANGER_NUEVA_DESDE
  { groupR: 11, nombre: 'COURIER',              alias: ['courier'] },
  { groupR: 12, nombre: 'KUGA',                 alias: ['kuga'] },
  { groupR: 13, nombre: 'OTROS',                alias: ['otro', 'otros'] },
  { groupR: 14, nombre: 'TRANSIT',              alias: ['transit'] },
  { groupR: 15, nombre: 'MONDEO',               alias: ['mondeo'] },
  { groupR: 16, nombre: 'MUSTANG',              alias: ['mustang'] },
  { groupR: 17, nombre: 'F-150',                alias: ['f150', 'f 150', 'lobo'] },
  { groupR: 18, nombre: 'F-150 RAPTOR',         alias: ['f150 raptor', 'f 150 raptor', 'lobo raptor'] },
  { groupR: 19, nombre: 'TERRITORY',            alias: ['territory'] },
  { groupR: 20, nombre: 'BRONCO SPORT',         alias: ['bronco sport'] },
  { groupR: 22, nombre: 'MAVERICK',             alias: ['maverick'] },
  { groupR: 23, nombre: 'CARGO',                alias: ['cargo'] },
  { groupR: 24, nombre: 'RANGER (P703)',        alias: ['ranger', 'ranger p703'] },  // ver RANGER_NUEVA_DESDE
  { groupR: 25, nombre: 'F-250',                alias: ['f250', 'f 250'] },
  { groupR: 26, nombre: 'MACH-E',               alias: ['mach e', 'mache', 'mustang mach e'] },
  { groupR: 27, nombre: 'RANGER RAPTOR (P703)', alias: ['ranger raptor'] },
  { groupR: 28, nombre: 'BRONCO',               alias: ['bronco'] },
  { groupR: 30, nombre: 'EVEREST',              alias: ['everest'] },
];

const normalizar = (s) => String(s ?? '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/\+/g, ' plus ')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();
const compacto = (s) => normalizar(s).replace(/ /g, '');

function distancia(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
  }
  return d[a.length][b.length];
}

function detectar(texto) {
  const conEspacios = ` ${normalizar(texto)} `;
  const junto = compacto(texto);
  if (!junto) return null;

  // 1) Coincidencia exacta: gana el alias más largo ("ranger raptor" le gana a "ranger")
  let mejor = null;
  for (const m of MODELOS) {
    for (const alias of m.alias) {
      const a = compacto(alias);
      // los alias cortos ("ka") tienen que ser una palabra entera, para no matchear "kangoo" o "kart"
      const encontrado = a.length <= 3 ? conEspacios.includes(` ${normalizar(alias)} `) : junto.includes(a);
      if (encontrado && (!mejor || a.length > mejor.largo)) mejor = { modelo: m, largo: a.length, metodo: 'exacto' };
    }
  }
  if (mejor) return mejor;

  // 2) Errores de tipeo ("territori", "ranguer", "ecosprot"): se compara palabra por palabra y de a pares
  const palabras = normalizar(texto).split(' ').filter(Boolean);
  const candidatos = [...palabras, ...palabras.slice(1).map((p, i) => palabras[i] + p)];
  for (const m of MODELOS) {
    for (const alias of m.alias) {
      const a = compacto(alias);
      if (a.length < 5) continue;
      const tolerancia = a.length >= 8 ? 2 : 1;
      for (const c of candidatos) {
        const dist = distancia(c, a);
        if (dist <= tolerancia && (!mejor || dist < mejor.dist || (dist === mejor.dist && a.length > mejor.largo))) {
          mejor = { modelo: m, largo: a.length, dist, metodo: 'aproximado' };
        }
      }
    }
  }
  return mejor;
}

const t = $('When Executed by Another Workflow').first().json;
const entrada = $input.first().json;
const vehiculo = entrada.response && !entrada.response.allNull ? entrada.response : {};

// Si Ford ya conoce el vehículo, no hace falta adivinar
if (vehiculo.modelGroup) {
  return [{ json: { ...entrada, groupR: String(vehiculo.modelGroup), modeloDetectado: vehiculo.modelName || vehiculo.model || null, metodo: 'ford' } }];
}

// Si groupR ya viene como número, se usa directo
if (/^\d+$/.test(String(t.groupR ?? '').trim())) {
  return [{ json: { ...entrada, groupR: String(t.groupR).trim(), modeloDetectado: null, metodo: 'entrada' } }];
}

// El modelo escrito por el cliente puede venir en "modelo" o, por error, en "groupR"
const textoModelo = String(t.modelo || t.model || t.vehiculo || t.groupR || '').trim();
const match = detectar(textoModelo);

if (!match) {
  throw new Error(
    `No reconocí el modelo "${textoModelo}". Pedile al cliente que lo confirme. ` +
    `Modelos válidos: ${MODELOS.filter(m => m.groupR !== 13).map(m => m.nombre).join(', ')}`
  );
}

let { groupR, nombre } = match.modelo;

// Ranger: la vieja (9) y la nueva P703 (24) son grupos distintos
let anio = Number((textoModelo.match(/\b(19|20)\d{2}\b/) || [])[0]) || Number(t.anio) || Number(vehiculo.modelYear) || null;
if (groupR === 24 && anio && anio < RANGER_NUEVA_DESDE) {
  groupR = 9;
  nombre = 'RANGER';
}

return [{
  json: {
    ...entrada,
    groupR: String(groupR),
    modeloDetectado: nombre,
    anio,
    metodo: match.metodo,
  }
}];

// ==========================================================
// Arma el body de alta de contacto (POST /contact) con los datos del cliente
// ==========================================================
const USER_CDSID = 'v-moure'; // mismo usuario que usa la búsqueda de clientes

const t = $('When Executed by Another Workflow').first().json;
const entrada = $input.first().json; // viene de "Detectar modelo"
const resp = entrada.response || {};
const vehiculo = resp.allNull ? {} : resp;

const limpiar = (v) => String(v ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');

// Patente y chasis: si en "patente" vino un VIN de 17 caracteres, se toma como chasis
const ingreso = limpiar(t.patente);
const chasisTrigger = limpiar(t.chasis || t.chassis || t.chassi);
const plate = ingreso.length === 17 ? null : (ingreso || null);
const chassi = chasisTrigger.length === 17 ? chasisTrigger : (ingreso.length === 17 ? ingreso : null);

// Teléfono: se sacan 54 / 9 / 0 del principio y se separa característica + número
// (igual que la web: "11" + "23456789")
const tel = String(t.telefono || '').replace(/\D/g, '').replace(/^54/, '').replace(/^9/, '').replace(/^0/, '');
const ddd = tel.startsWith('11') ? '11' : tel.slice(0, 3);
const numero = tel.slice(ddd.length);

const nombre = String(t.nombre || '').trim();
const apellido = String(t.apellido || '').trim();
const dni = String(t.dni || '').replace(/\D/g, '');
const email = String(t.email || '').trim().toLowerCase();

// groupR: primero el que calculó "Detectar modelo", después el de Ford
const groupR = entrada.groupR ?? vehiculo.modelGroup ?? null;

const faltan = Object.entries({ patente: plate || chassi, nombre, apellido, dni, email, telefono: numero, groupR })
  .filter(([, v]) => v === null || v === undefined || String(v).trim() === '')
  .map(([k]) => k);
if (tel && tel.length !== 10) faltan.push('telefono (tiene que tener 10 dígitos con la característica, ej: 1123456789)');
if (faltan.length) {
  throw new Error(`Faltan datos para dar de alta al cliente: ${faltan.join(', ')}`);
}

// Dirección: opcional, se manda si el agente la pidió
const texto = (v) => (v === null || v === undefined || String(v).trim() === '' ? null : String(v).trim());

const body = {
  plate,
  chassi,
  groupR: String(groupR),
  typeOfPerson: '1',
  typeOfPersonConductor: '1',
  nationalId: dni,
  nationalIdConductor: dni,
  firstname: nombre,
  firstnameConductor: nombre,
  lastname: apellido,
  lastnameConductor: apellido,
  email,
  emailConductor: email,
  emailConductorRequiredCvp: true,
  emailOwnerRequiredCvp: true,
  dddPrimaryPhone: ddd,
  primaryPhone: numero,
  dddPrimaryPhoneConductor: ddd,
  primaryPhoneConductor: numero,
  dddAnotherPhone: ddd,
  anotherPhone: numero,
  favoriteContactVO: [{ description: 'EMAIL' }],
  favoriteContactConductorVO: [{ description: 'EMAIL' }],
  countryCode: 'ARG',
  division: 1,
  customerAddress: texto(t.direccion),
  customerAddressNumber: texto(t.altura),
  customerAddressComplement: null,
  customerCity: texto(t.ciudad),
  customerNeighborhood: texto(t.barrio || t.ciudad),
  customerState: texto(t.provincia),
  customerZip: texto(t.cp),
  model: vehiculo.model ?? null,
  modelYear: vehiculo.modelYear ?? entrada.anio ?? null,
  engine: vehiculo.engineCode ?? null,
  modelVehicleElectricVehicle: 'N',
  vehicleProductionYear: null,
  warrantyDate: null,
  satisfaction: 'Y',
  user: USER_CDSID,
};

return [{ json: { body } }];

// Datos del cliente recién creado para guardar en agenda_ford
// (mismos campos que guarda Code2 en get_user, para que el resto del flujo funcione igual)
const { body } = $('Armar alta de contacto1').first().json;
const modelo = $('Detectar modelo1').first().json;
const r = $input.first().json;

function getKmFrequency(groupR, modelYear) {
  const year = parseInt(modelYear) || 0;
  switch (groupR) {
    case 1: case 2: case 3: case 4: case 6: case 8: case 11: case 12: case 13:
    case 15: case 16: case 17: case 18: case 22: case 23: case 25:
      return 15000;
    case 9:  return year >= 2024 ? 16000 : 10000; // RANGER generaciones viejas
    case 14: return year >= 2021 ? 16000 : 15000; // TRANSIT
    case 19: return 10000;                        // TERRITORY
    case 20: case 24: case 26: case 27: case 28: case 30:
      return 16000;
    default: return 15000;
  }
}

const groupR = Number(body.groupR) || null;

return [{
  json: {
    customerK: r.customerIdOwner ?? null,
    model: modelo.modeloDetectado || body.model || null,
    model_id: groupR,
    plate: body.plate,
    chassi: body.chassi,
    nationalId: body.nationalId,
    firstname: body.firstname,
    lastname: body.lastname,
    email: body.email,
    id_conversation: String($('When Executed by Another Workflow').first().json.id_conversation),
    company: 1,
    km_frequency: getKmFrequency(groupR, body.modelYear),
  }
}];

// ==========================================================
// Vehículo según Ford: después del alta se busca el cliente en Ford,
// que completa modelo, año y chasis desde su propia base de vehículos.
// Solo se guardan en agenda_ford los datos que Ford devolvió, para no
// pisar con vacíos lo que ya guardó el alta.
// ==========================================================
function getKmFrequency(groupR, modelYear) {
  const year = parseInt(modelYear) || 0;
  switch (groupR) {
    case 1: case 2: case 3: case 4: case 6: case 8: case 11: case 12: case 13:
    case 15: case 16: case 17: case 18: case 22: case 23: case 25:
      return 15000;
    case 9:  return year >= 2024 ? 16000 : 10000; // RANGER generaciones viejas
    case 14: return year >= 2021 ? 16000 : 15000; // TRANSIT
    case 19: return 10000;                        // TERRITORY
    case 20: case 24: case 26: case 27: case 28: case 30:
      return 16000;
    default: return 15000;
  }
}

let raw = $input.first().json;
if (Array.isArray(raw)) raw = raw[0] || {};
const cliente = raw && !raw.error ? raw : {};

const groupR = Number(cliente.groupR) || null;

const resultado = {
  id_conversation: String($('When Executed by Another Workflow').first().json.id_conversation),
  customerK: cliente.customerK ?? null,
  model: cliente.model || null,
  model_id: groupR,
  chassi: cliente.chassi || null,
  km_frequency: groupR ? getKmFrequency(groupR, cliente.modelYear) : null,
};

for (const campo of Object.keys(resultado)) {
  if (resultado[campo] == null) delete resultado[campo];
}

return [{ json: resultado }];

const items = $input.all();

// 👇 Traemos el nombre del asesor desde el nodo de entrada del workflow
const inputData = $('When Executed by Another Workflow').first().json;
const nombreAsesor = inputData.NombreAsesor?.trim() || null;

function normalizar(str) {
  return str
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

const NOMBRES_BLOQUEADOS = ["VAELLO HUGO HERNAN", "ROMINA FILI"];

const todosLosAsesores = items
  .map(i => i.json)
  .filter(a => {
    if (a.advisorId === 146715) return false;
    const nombreNormalizado = normalizar(a.advisorName || "");
    const estaBloqueado = NOMBRES_BLOQUEADOS.some(bloqueado =>
      nombreNormalizado.includes(normalizar(bloqueado))
    );
    if (estaBloqueado) return false;
    return true;
  });

if (nombreAsesor) {
  const palabras = normalizar(nombreAsesor).split(/\s+/).filter(p => p.length > 0);
  const match = todosLosAsesores.find(a => {
    const nombre = normalizar(a.advisorName || '');
    return palabras.every(p => nombre.includes(p));
  });
  if (match) {
    return {
      json: {
        advisorId: match.advisorId,
        advisorName: match.advisorName,
        schedules: match.schedules
      }
    };
  }
}

const randomIndex = Math.floor(Math.random() * todosLosAsesores.length);
const selected = todosLosAsesores[randomIndex];
return {
  json: {
    advisorId: selected.advisorId,
    advisorName: selected.advisorName,
    schedules: selected.schedules
  }
};

const items = $input.all();
if (!items.length) throw new Error('No hay datos de entrada');

let raw = items[0].json;
let cliente;
if (Array.isArray(raw)) {
  if (!raw.length) throw new Error('El array de entrada está vacío');
  cliente = raw[0];
} else {
  cliente = raw;
}
if (!cliente || typeof cliente !== 'object') throw new Error('Formato de entrada inválido');

function getKmFrequency(groupR, modelYear) {
  const year = parseInt(modelYear) || 0;

  switch (groupR) {
    case 1:  return 15000; // KA
    case 2:
    case 3:  return 15000; // FIESTA
    case 4:  return 15000; // ECOSPORT
    case 6:  return 15000; // FOCUS
    case 8:  return 15000; // S-MAX
    case 9:                // RANGER generaciones viejas
      return year >= 2024 ? 16000 : 10000;
    case 11: return 15000; // COURIER
    case 12: return 15000; // KUGA
    case 13: return 15000; // OTROS
    case 14:               // TRANSIT
      return year >= 2021 ? 16000 : 15000;
    case 15: return 15000; // MONDEO
    case 16: return 15000; // MUSTANG
    case 17:
    case 25: return 15000; // F-150 / F-250
    case 18: return 15000; // F-150 RAPTOR
    case 19: return 10000; // TERRITORY
    case 20: return 16000; // BRONCO SPORT
    case 22: return 15000; // MAVERICK
    case 23: return 15000; // CARGO
    case 24: return 16000; // RANGER (P703)
    case 26: return 16000; // MACH-E
    case 27: return 16000; // RANGER RAPTOR (P703)
    case 28: return 16000; // BRONCO
    case 30: return 16000; // EVEREST
    default: return 15000; // fallback general
  }
}

// --- Determinar si lo que ingresó el cliente es patente o chasis ---
const patenteCliente = ($('When Executed by Another Workflow').first().json.patente || '').toUpperCase();
const tipoIngreso = patenteCliente.length === 7 ? 'plate' : 'chassi';

// Si el cliente ingresó un chasis (tipoIngreso === 'chassi'), se usa ESE valor,
// ignorando por completo el cliente.chassi que devuelve la API.
// Si ingresó una patente, no se toca nada: sigue el chasis que vino de la API.
const chassiFinal = tipoIngreso === 'chassi'
  ? patenteCliente
  : (cliente.chassi || null);

const resultado = {
  customerK:       cliente.customerK ?? null,
  model:           cliente.model || null,
  model_id:        cliente.groupR || null,
  plate:           cliente.plate || null,
  chassi:          chassiFinal,
  nationalId:      cliente.nationalId || null,
  firstname:       cliente.firstname || null,
  lastname:        cliente.lastname || null,
  email:           cliente.email || null,
  id_conversation: String($("When Executed by Another Workflow").first().json.id_conversation),
  company:         1,
  km_frequency:    getKmFrequency(cliente.groupR, cliente.modelYear),
};

return [{ json: resultado }];

// Obtenemos todos los items del input
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) throw new Error('El array raíz está vacío');
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const services = Array.isArray(root.response) ? root.response : [];
if (!services.length) {
  throw new Error('No se encontraron servicios en root.response');
}

// 🔥 Normaliza texto (sin tildes, minúscula)
function normalizeText(text) {
  return (text ?? "")
    .toString()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

const output = [];

for (const svc of services) {
  const serviceNameNorm = normalizeText(svc.serviceName);

  // ❌ Excluir Servicio Móvil (incluye "(Online)")
  if (serviceNameNorm.includes("servicio movil")) {
    continue;
  }

  // ❌ Excluir Lavado Complementario (incluye typo)
  if (
    serviceNameNorm.includes("lavado complementario") ||
    serviceNameNorm.includes("lavado complemetario")
  ) {
    continue;
  }

  // ❌ Excluir Lavado de Cortesía
  if (
    serviceNameNorm.includes("lavado de cortesia") ||
    serviceNameNorm.includes("lavado cortesia")
  ) {
    continue;
  }

  const servicesByModelGroup = Array.isArray(svc.servicesByModelGroup)
    ? svc.servicesByModelGroup
    : [];

  let promo = null;
  for (const mg of servicesByModelGroup) {
    if (mg.promotionalActive) {
      promo = mg;
      break;
    }
  }

  const price = promo && typeof promo.promotionalPrice === 'number'
    ? promo.promotionalPrice
    : svc.servicePrice ?? null;

  const simplified = {
    serviceId: svc.serviceId,
    name: svc.serviceName,
    description: svc.name ?? null,
    price,
    normalPrice: svc.servicePrice ?? null,
    isPromo: !!(promo && promo.promotionalActive),
  };

  output.push({ json: simplified });
}

return output;

// Obtener input
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

// El input que mostraste es:
// [ { httpCode, message, response: [ { ...mantenimiento }, ... ] } ]
let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) throw new Error('El array raíz está vacío');
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const list = Array.isArray(root.response) ? root.response : [];
if (!list.length) {
  throw new Error('No se encontraron mantenimientos en root.response');
}

// Normalizamos fecha a "solo día"
function toDateOnly(value) {
  if (!value) return null;
  const d = new Date(value);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}

const now = new Date();
now.setHours(0, 0, 0, 0);

const output = [];

for (const item of list) {
  const start = toDateOnly(item.modelStartDate);
  const end = toDateOnly(item.modelEndDate);

  if (!start || !end) {
    continue; // si no tiene fechas válidas, lo salteamos
  }

  // vigente si: start <= now <= end
  if (start <= now && now <= end) {
    output.push({
      json: {
        maintenanceCode: item.maintenanceCode,
        months: item.mounths ?? null, // el campo viene como "mounths"
        price: item.price ?? null,
      },
    });
  }
}

return output;

// Obtenemos los items de entrada
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

// El input viene como:
// [ { httpCode, message, response: [ { ...servicio }, ... ] } ]
let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) {
    throw new Error('El array raíz está vacío');
  }
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const list = Array.isArray(root.response) ? root.response : [];
if (!list.length) {
  throw new Error('No se encontraron servicios en root.response');
}

// Helper para normalizar fechas a "solo día"
function toDateOnly(value) {
  if (!value) return null;
  const d = new Date(value);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}

// Helper para parsear montos (string o number)
function toNumber(value) {
  if (value === null || value === undefined) return 0;
  if (typeof value === 'number') return value;
  const s = String(value).replace(',', '.');
  const n = Number(s);
  return isNaN(n) ? 0 : n;
}

// Fecha actual (Argentina, pero solo día nos alcanza)
const now = new Date();
now.setHours(0, 0, 0, 0);

// Filtramos servicios vigentes hoy
const vigentes = list.filter(item => {
  const start = toDateOnly(item.modelStartDate);
  const end = toDateOnly(item.modelEndDate);
  if (!start || !end) return false;
  return start <= now && now <= end;
});

if (!vigentes.length) {
  throw new Error('No hay servicios vigentes para la fecha actual');
}

// Tomamos el primero vigente (en tu caso el de diciembre)
const svc = vigentes[0];

// Calculamos precio de ítems
