for (const diaAsesor of listaAsesores) {
  const fecha = diaAsesor.fecha || diaAsesor.fechaActual;
  if (!fecha) continue;

  if (fecha === fechaHoy) continue;
  if (esSabado(fecha)) continue;
  if (!fechaCoincideConFiltro(fecha, fechaEspecifica)) continue;

  const mecanicosDelDia = agendaMecanicos[fecha] || [];
  if (mecanicosDelDia.length === 0) continue;

  for (const asesor of (diaAsesor.detalleAsesores || [])) {
    for (const slotRecepcion of (asesor.slotsDisponibles || [])) {
      const minRecepcion = toMinutes(slotRecepcion);

      // La recepción no puede exceder las 13:00 para garantizar que el servicio finalice a las 14:00 o antes
      if (minRecepcion + DURACION_SERVICIO_MINUTOS > HORA_LIMITE_FIN_MINUTOS) continue;
      if (!horaCoincideConFiltro(slotRecepcion, horaEspecifica)) continue;

      let asignado = false;

      for (const mec of mecanicosDelDia) {
        if (asignado) break;

        for (let i = 0; i < mec.intervalos.length; i++) {
          const [iniMec, finMec] = mec.intervalos[i];

          const inicioAtencion = Math.max(minRecepcion, iniMec);
          const finAtencion = inicioAtencion + DURACION_SERVICIO_MINUTOS;
          const diferenciaEspera = inicioAtencion - minRecepcion;

          if (
            diferenciaEspera >= 0 &&
            diferenciaEspera <= DIFERENCIA_MAXIMA_MINUTOS &&
            finAtencion <= finMec &&
            finAtencion <= HORA_LIMITE_FIN_MINUTOS
          ) {
            turnosDisponibles.push({
              json: {
                fecha,
                fechaTexto: formatearFechaConDia(fecha),
                horarioRecepcion: slotRecepcion,
