// ---------- Selección final: más próximos primero, sin horario repetido, máx. 2 por fecha ----------
turnosDisponibles.sort((a, b) => {
  const diffA = diffDias(a.json.fecha, fechaReferencia);
  const diffB = diffDias(b.json.fecha, fechaReferencia);
  if (diffA !== diffB) return diffA - diffB;
  if (a.json.fecha !== b.json.fecha) return a.json.fecha < b.json.fecha ? -1 : 1;
  return toMinutes(a.json.horarioRecepcion) - toMinutes(b.json.horarioRecepcion);
});

const horariosUsados = new Set();
const conteoPorFecha = {};
const turnosFinales = [];

for (const turno of turnosDisponibles) {
  const { fecha, horarioRecepcion } = turno.json;

  if (horariosUsados.has(horarioRecepcion)) continue;
  if ((conteoPorFecha[fecha] || 0) >= MAX_TURNOS_POR_DIA) continue;

  turnosFinales.push(turno);
  horariosUsados.add(horarioRecepcion);
  conteoPorFecha[fecha] = (conteoPorFecha[fecha] || 0) + 1;
}

if (turnosFinales.length === 0) {
  return [{
    json: {
      turnosEncontrados: 0,
