const norm = (t) => String(t ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const USO = {
  'diagnostico general': 'falla no clara, varias fallas a la vez, luz testigo / check engine sin otro dato, o no sabe qué tiene',
  'diagnostico motor y transmision': 'motor, caja, embrague, pérdida de potencia, tironea, no arranca, humo, temperatura, consumo, luz de check engine con síntomas de motor, ruidos del motor',
