// ==========================================================
// Detectar modelo: convierte el modelo que escribió el cliente en el groupR de Ford
// ==========================================================
// Si Ford ya conoce el vehículo (Ford - Buscar Vehiculo trae modelGroup), se usa ese.
// Si no, se busca el texto del cliente (campo "modelo" del trigger) en esta tabla.

// La Ranger nueva (P703) es otro groupR: si el cliente dice el año, se usa para decidir
const RANGER_NUEVA_DESDE = 2023;

// groupR -> nombres con los que lo puede escribir el cliente.
// Ids y nombres del catálogo de Agenda Ford: GET /agenda-scheduling/api/internal/modelVehicle/ARG/1
// (el 3 es un FIESTA duplicado en AF: se usa el 2)
const MODELOS = [
  { groupR: 1,  nombre: 'KA',                   alias: ['ka', 'ka plus', 'ka+', 'ka freestyle'] },
  { groupR: 2,  nombre: 'FIESTA',               alias: ['fiesta', 'fiesta kinetic', 'fiesta max'] },
  { groupR: 4,  nombre: 'ECOSPORT',             alias: ['ecosport', 'eco sport'] },
  { groupR: 6,  nombre: 'FOCUS',                alias: ['focus'] },
  { groupR: 8,  nombre: 'S-MAX',                alias: ['s max', 'smax'] },
  { groupR: 9,  nombre: 'RANGER',               alias: [] },                 // Ranger anterior: se elige por año, ver RANGER_NUEVA_DESDE
  { groupR: 11, nombre: 'COURIER',              alias: ['courier'] },
  { groupR: 12, nombre: 'KUGA',                 alias: ['kuga'] },
  { groupR: 13, nombre: 'OTROS',                alias: ['otro', 'otros'] },
  { groupR: 14, nombre: 'TRANSIT',              alias: ['transit'] },
  { groupR: 15, nombre: 'MONDEO',               alias: ['mondeo'] },
  { groupR: 16, nombre: 'MUSTANG',              alias: ['mustang'] },
  { groupR: 17, nombre: 'F-150',                alias: ['f150', 'f 150', 'lobo'] },
  { groupR: 18, nombre: 'F-150 RAPTOR',         alias: ['f150 raptor', 'f 150 raptor', 'lobo raptor'] },
  { groupR: 19, nombre: 'TERRITORY',            alias: ['territory'] },
  { groupR: 20, nombre: 'BRONCO SPORT',         alias: ['bronco sport'] },
  { groupR: 22, nombre: 'MAVERICK',             alias: ['maverick'] },
  { groupR: 23, nombre: 'CARGO',                alias: ['cargo'] },
  { groupR: 24, nombre: 'RANGER (P703)',        alias: ['ranger', 'ranger p703'] },  // ver RANGER_NUEVA_DESDE
  { groupR: 25, nombre: 'F-250',                alias: ['f250', 'f 250'] },
  { groupR: 26, nombre: 'MACH-E',               alias: ['mach e', 'mache', 'mustang mach e'] },
  { groupR: 27, nombre: 'RANGER RAPTOR (P703)', alias: ['ranger raptor'] },
  { groupR: 28, nombre: 'BRONCO',               alias: ['bronco'] },
  { groupR: 30, nombre: 'EVEREST',              alias: ['everest'] },
];

const normalizar = (s) => String(s ?? '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/\+/g, ' plus ')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();
const compacto = (s) => normalizar(s).replace(/ /g, '');

function distancia(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
  }
  return d[a.length][b.length];
}

function detectar(texto) {
  const conEspacios = ` ${normalizar(texto)} `;
  const junto = compacto(texto);
  if (!junto) return null;

  // 1) Coincidencia exacta: gana el alias más largo ("ranger raptor" le gana a "ranger")
  let mejor = null;
  for (const m of MODELOS) {
    for (const alias of m.alias) {
      const a = compacto(alias);
      // los alias cortos ("ka") tienen que ser una palabra entera, para no matchear "kangoo" o "kart"
      const encontrado = a.length <= 3 ? conEspacios.includes(` ${normalizar(alias)} `) : junto.includes(a);
      if (encontrado && (!mejor || a.length > mejor.largo)) mejor = { modelo: m, largo: a.length, metodo: 'exacto' };
    }
  }
  if (mejor) return mejor;

  // 2) Errores de tipeo ("territori", "ranguer", "ecosprot"): se compara palabra por palabra y de a pares
  const palabras = normalizar(texto).split(' ').filter(Boolean);
  const candidatos = [...palabras, ...palabras.slice(1).map((p, i) => palabras[i] + p)];
  for (const m of MODELOS) {
    for (const alias of m.alias) {
      const a = compacto(alias);
      if (a.length < 5) continue;
      const tolerancia = a.length >= 8 ? 2 : 1;
      for (const c of candidatos) {
        const dist = distancia(c, a);
        if (dist <= tolerancia && (!mejor || dist < mejor.dist || (dist === mejor.dist && a.length > mejor.largo))) {
          mejor = { modelo: m, largo: a.length, dist, metodo: 'aproximado' };
        }
      }
    }
  }
  return mejor;
}

