  }

  const servicesByModelGroup = Array.isArray(svc.servicesByModelGroup)
    ? svc.servicesByModelGroup
    : [];

  let promo = null;
  for (const mg of servicesByModelGroup) {
    if (mg.promotionalActive) {
      promo = mg;
      break;
    }
  }

  const price = promo && typeof promo.promotionalPrice === 'number'
    ? promo.promotionalPrice
    : svc.servicePrice ?? null;

  const simplified = {
    serviceId: svc.serviceId,
    name: svc.serviceName,
