      if (!horaCoincideConFiltro(slotRecepcion, horaEspecifica)) continue;

      let asignado = false;

      for (const mec of mecanicosDelDia) {
        if (asignado) break;

        for (let i = 0; i < mec.intervalos.length; i++) {
          const [iniMec, finMec] = mec.intervalos[i];

          const inicioAtencion = Math.max(minRecepcion, iniMec);
          const finAtencion = inicioAtencion + DURACION_SERVICIO_MINUTOS;
          const diferenciaEspera = inicioAtencion - minRecepcion;

          if (
            diferenciaEspera >= 0 &&
            diferenciaEspera <= DIFERENCIA_MAXIMA_MINUTOS &&
            finAtencion <= finMec &&
            finAtencion <= HORA_LIMITE_FIN_MINUTOS
          ) {
            turnosDisponibles.push({
              json: {
                fecha,
                fechaTexto: formatearFechaConDia(fecha),
                horarioRecepcion: slotRecepcion,
                asesorId: asesor.advisorId,
                asesorNombre: asesor.advisorName,
                mecanicoNombre: mec.nombre,
                huecoMecanico: `${toHHMM(inicioAtencion)} - ${toHHMM(finAtencion)}`,
                diferenciaEsperaMinutos: diferenciaEspera
              }
            });

            // Descontar intervalo consumido del mecánico
            const nuevosIntervalos = [];
            if (inicioAtencion > iniMec) {
              nuevosIntervalos.push([iniMec, inicioAtencion]);
            }
            if (finMec > finAtencion) {
              nuevosIntervalos.push([finAtencion, finMec]);
            }
            mec.intervalos.splice(i, 1, ...nuevosIntervalos);

            asignado = true;
            break;
          }
        }
      }
    }
  }
}

// ---------- Selección final: más próximos primero, sin horario repetido, máx. 2 por fecha ----------
turnosDisponibles.sort((a, b) => {
  const diffA = diffDias(a.json.fecha, fechaReferencia);
  const diffB = diffDias(b.json.fecha, fechaReferencia);
  if (diffA !== diffB) return diffA - diffB;
  if (a.json.fecha !== b.json.fecha) return a.json.fecha < b.json.fecha ? -1 : 1;
  return toMinutes(a.json.horarioRecepcion) - toMinutes(b.json.horarioRecepcion);
});

const horariosUsados = new Set();
const conteoPorFecha = {};
const turnosFinales = [];

for (const turno of turnosDisponibles) {
  const { fecha, horarioRecepcion } = turno.json;

  if (horariosUsados.has(horarioRecepcion)) continue;
  if ((conteoPorFecha[fecha] || 0) >= MAX_TURNOS_POR_DIA) continue;

  turnosFinales.push(turno);
  horariosUsados.add(horarioRecepcion);
  conteoPorFecha[fecha] = (conteoPorFecha[fecha] || 0) + 1;
}

if (turnosFinales.length === 0) {
  return [{
    json: {
      turnosEncontrados: 0,
      mensaje: "No hay turnos disponibles para los filtros solicitados"
    }
  }];
}

return turnosFinales;

