const normalizar = (s) => String(s ?? '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/\+/g, ' plus ')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();
const compacto = (s) => normalizar(s).replace(/ /g, '');

function distancia(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
  }
  return d[a.length][b.length];
}

function detectar(texto) {
  const conEspacios = ` ${normalizar(texto)} `;
  const junto = compacto(texto);
  if (!junto) return null;

  // 1) Coincidencia exacta: gana el alias más largo ("ranger raptor" le gana a "ranger")
  let mejor = null;
  for (const m of MODELOS) {
    for (const alias of m.alias) {
      const a = compacto(alias);
      // los alias cortos ("ka") tienen que ser una palabra entera, para no matchear "kangoo" o "kart"
      const encontrado = a.length <= 3 ? conEspacios.includes(` ${normalizar(alias)} `) : junto.includes(a);
      if (encontrado && (!mejor || a.length > mejor.largo)) mejor = { modelo: m, largo: a.length, metodo: 'exacto' };
    }
  }
  if (mejor) return mejor;

  // 2) Errores de tipeo ("territori", "ranguer", "ecosprot"): se compara palabra por palabra y de a pares
  const palabras = normalizar(texto).split(' ').filter(Boolean);
  const candidatos = [...palabras, ...palabras.slice(1).map((p, i) => palabras[i] + p)];
  for (const m of MODELOS) {
    for (const alias of m.alias) {
      const a = compacto(alias);
      if (a.length < 5) continue;
      const tolerancia = a.length >= 8 ? 2 : 1;
      for (const c of candidatos) {
        const dist = distancia(c, a);
        if (dist <= tolerancia && (!mejor || dist < mejor.dist || (dist === mejor.dist && a.length > mejor.largo))) {
          mejor = { modelo: m, largo: a.length, dist, metodo: 'aproximado' };
        }
      }
    }
  }
  return mejor;
}

const t = $('When Executed by Another Workflow').first().json;
